import{_ as s,c as i,o as a,a4 as e}from"./chunks/framework.ssOvXUgL.js";const g=JSON.parse('{"title":"config 工具类","description":"","frontmatter":{},"headers":[],"relativePath":"guide/global/config.md","filePath":"guide/global/config.md","lastUpdated":1728809929000}'),t={name:"guide/global/config.md"},n=e(`<h1 id="config-工具类" tabindex="-1">config 工具类 <a class="header-anchor" href="#config-工具类" aria-label="Permalink to &quot;config 工具类&quot;">​</a></h1><p>bot 在启动之初会在 <code>config</code> 目录下创建一系列配置文件。而该工具类所做的就是获取这些配置文件内容，并使开发者能够较为方便的实时获取它们。</p><p>工具类本质为一个对象，包含一个 <code>register()</code> 方法与多个与配置文件名同名的属性。如 <code>config.base</code> 对应 <code>base.yml</code>、<code>config.directive</code> 对应 <code>directive.yml</code>。</p><p>具体 api 调用可以翻阅 <a href="./../../api/global/config.html">工具类 Config Api</a></p><h2 id="配置文件对象" tabindex="-1">配置文件对象 <a class="header-anchor" href="#配置文件对象" aria-label="Permalink to &quot;配置文件对象&quot;">​</a></h2><p>每与配置文件名同名的属性均为一个<a href="./../../api/global/config.html#配置文件对象">配置文件对象</a>。</p><h3 id="配置文件内容" tabindex="-1">配置文件内容 <a class="header-anchor" href="#配置文件内容" aria-label="Permalink to &quot;配置文件内容&quot;">​</a></h3><p>以获取配置文件 <code>base.yml</code> 中的 <code>master</code> 号码为例，调用方式：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> bot </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;ROOT&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">bot.config.base.master;</span></span></code></pre></div><p>其他配置文件的详细内容参考 <a href="./../../config/base.html">基本配置</a></p><h3 id="注册配置文件重载事件监听" tabindex="-1">注册配置文件重载事件监听 <a class="header-anchor" href="#注册配置文件重载事件监听" aria-label="Permalink to &quot;注册配置文件重载事件监听&quot;">​</a></h3><p>开发者可能期望当配置文件发生变化时执行一些自己的操作。例如某个属性值依赖于配置文件的 <code>master</code> 属性，那么当 <code>master</code> 发生变化时，理应同步更改这个属性值。</p><p>那么可以通过配置文件对象携带的 <code>on()</code> 方法，来监听配置文件内容的变化。</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 以 base.yml 举例</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">bot.config.base.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">on</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">( </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;refresh&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, ( </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">newCfg</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">oldCfg</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {} );</span></span></code></pre></div><p>该事件当且仅当<strong>文件内容发生变化</strong>并<strong>执行了<code>#refresh</code>指令</strong>时触发，并默认情况下向发送指令方发送提示 <code>xxx.yml 重新加载完毕</code>。</p><p>其中回调函数参数 <code>newCfg</code> 与 <code>oldCfg</code> 分别表示刷新前后的配置项值。</p><p>当回调函数返回 <code>string</code> 类型的值时，将替代默认的刷新成功的打印文本（如果你不希望发送任何提示消息，则返回 <code>&quot;&quot;</code>）。</p><p>下面是一个示例，用于监控 <code>base.yml</code> 中的 <code>master</code> 内容变更，并同步到自定义的参数 <code>botMaster</code>。且当 <code>master</code> 内容变更时，发送响应消息 <code>bot 主人账号重载成功</code>，反之不发送任何内容。</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> bot </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;ROOT&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> botMaster </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> bot.config.master;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">bot.config.base.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">on</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">( </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;refresh&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, ( </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">newCfg</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">oldCfg</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ( newCfg.master </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!==</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> oldCfg.master ) {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        botMaster </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> newCfg.master;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        return</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;bot 主人账号重载成功&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">} );</span></span></code></pre></div><h3 id="清除配置文件重载事件监听事件" tabindex="-1">清除配置文件重载事件监听事件 <a class="header-anchor" href="#清除配置文件重载事件监听事件" aria-label="Permalink to &quot;清除配置文件重载事件监听事件&quot;">​</a></h3><p>可以通过配置文件对象携带的 <code>clear()</code> 方法，来清除配置文件重载事件监听事件。</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> bot </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;ROOT&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">bot.config.base.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">clear</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">( </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;refresh&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> );</span></span></code></pre></div><blockquote><p>注意：这将会清除掉 bot 对应配置文件对象的重载事件，对应配置文件将无法正常响应 <code>#refresh</code> 重载指令。若非你有特殊要求（例如重写框架的重载逻辑），否则我们不建议开发者操作该方法。</p></blockquote><h2 id="注册插件配置文件" tabindex="-1">注册插件配置文件 <a class="header-anchor" href="#注册插件配置文件" aria-label="Permalink to &quot;注册插件配置文件&quot;">​</a></h2><p>可通过 <code>register()</code> 方法来为插件注册并创建一个配置文件，具体请查看 <a href="./../../guide/plugin/config_file.html#注册插件配置文件">注册插件配置文件</a>。</p>`,25),h=[n];function l(p,k,o,d,r,c){return a(),i("div",null,h)}const y=s(t,[["render",l]]);export{g as __pageData,y as default};
